package com.example.simpleaccountant.ui.suppliers;import android.app.AlertDialog;import android.content.Intent;import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.example.simpleaccountant.R;import com.example.simpleaccountant.data.dao.SupplierDao;
public class SupplierListActivity extends AppCompatActivity{private SupplierDao dao;private SupplierAdapter ad;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_list_search);dao=new SupplierDao(this);RecyclerView rv=findViewById(R.id.recyclerView);rv.setLayoutManager(new LinearLayoutManager(this));ad=new SupplierAdapter(s->new AlertDialog.Builder(this).setMessage("Delete supplier?").setPositiveButton("Yes",(d,w)->{dao.deleteSupplier(s.getId());load("");}).setNegativeButton("No",null).show());rv.setAdapter(ad);EditText sr=findViewById(R.id.etSearch);sr.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence a,int b,int c,int d){} public void onTextChanged(CharSequence x,int b,int c,int d){load(x.toString());} public void afterTextChanged(android.text.Editable e){}});findViewById(R.id.fabAdd).setOnClickListener(v->startActivity(new Intent(this,AddSupplierActivity.class)));}
@Override protected void onResume(){super.onResume();load("");}void load(String k){ad.setItems(k.isEmpty()?dao.getAllSuppliers():dao.searchSuppliers(k));}}
